  const pageDoc = await ctx.probe.get(new URL("/invoices", ctx.origin).toString(), {
    maxBytes: 65536,
    timeoutMs: 60000
  });
  const chunkRe = /\/_next\/static\/chunks\/[a-f0-9]+\.js/gi;
  let jsCorpus = "";
