// --- HackThisSite login-gated mission hubs (basic / application / playit extbasic+stego) --
const HTS_AUTH_GATE_RE =
  /Login Required|You must be logged in to use this page|require_auth/i;

const HTS_MAINTENANCE_RE =
  /Offline for Maintenance|temporarily offline for maintenance|htscdn\.org\/images\/maintenance/i;

const HTS_MISSION_NOT_FOUND_RE =
  /requested URL \/missions\/[a-z]+\/\d+\/? was not found|not found on this server/i;

const HTS_LOGIN_GATED_MISSION_NOTES: Record<string, string> = {
  basic:
    "HTS Basic mission hub is login-gated — documents HTML-comment password oracle and introductory web challenges behind authenticated access",
  forensic:
    "HTS Forensic mission hub is login-gated — documents disk-image and steganography CTF missions behind authenticated access",
  javascript:
    "HTS Javascript mission hub is login-gated — documents client-side script exploitation challenges behind authenticated access",
  programming:
    "HTS Programming mission hub is login-gated — documents algorithmic exploit programming challenges behind authenticated access",
  application:
    "HTS Application mission hub is login-gated — documents web application exploitation challenges behind authenticated access",
  extbasic:
    "HTS Extended Basic mission hub is login-gated — documents advanced HTML-level wargame challenges behind authenticated access",
  stego:
    "HTS Steganography mission hub is login-gated — documents image steganography CTF missions behind authenticated access",
  "missions-stego":
    "HTS Steganography mission category is login-gated — documents image/audio steganography CTF challenges behind authenticated access",
  realistic:
    "HTS Realistic mission instance is login-gated — documents advanced web application pentest challenges behind authenticated access"
};

type HtsLoginGatedHub =
  | { kind: "standard"; category: string }
  | { kind: "playit"; category: "extbasic" | "stego"; playSegment: string };

function parseHtsLoginGatedHub(pageUrl: string): HtsLoginGatedHub | null {
  const missionsStego = pageUrl.match(/hackthissite\.org\/missions\/stego(?:\/\d+)?\/?/i);
  if (missionsStego) return { kind: "standard", category: "missions-stego" };

  const standard = pageUrl.match(
    /hackthissite\.org\/missions\/(basic|forensic|javascript|programming|application)(?:\/\d+)?\/?/i
  );
  if (standard) return { kind: "standard", category: standard[1].toLowerCase() };

  const extbasic = pageUrl.match(/hackthissite\.org\/missions\/playit\/extbasic(?:\/\d+)?\/?/i);
  if (extbasic) return { kind: "playit", category: "extbasic", playSegment: "playit/extbasic" };

  const stego = pageUrl.match(/hackthissite\.org\/missions\/playit\/stego(?:\/\d+)?\/?/i);
  if (stego) return { kind: "playit", category: "stego", playSegment: "playit/stego" };

  const realistic = pageUrl.match(/hackthissite\.org\/missions\/realistic\/\d+\/?/i);
  if (realistic) return { kind: "standard", category: "realistic" };

  return null;
}

const clientSideHtsLoginGatedMissionHubEvidence: Rule = async (ctx) => {
  const pageUrl = ctx.home.finalUrl || ctx.origin;
  const hub = parseHtsLoginGatedHub(pageUrl);
  if (!hub) return NEGATIVE;
  const category = hub.category;
  const corpus = `${ctx.home.body}\n${pageUrl}`;
  const missionMissing = HTS_MISSION_NOT_FOUND_RE.test(corpus);
  const authGated = HTS_AUTH_GATE_RE.test(corpus);
  const maintenance = HTS_MAINTENANCE_RE.test(corpus);
  if (!authGated && !missionMissing && !maintenance) return NEGATIVE;
  const hits: { label: string; sample: string }[] = [];
  const missionPath =
    category === "missions-stego" ? "stego" : hub.kind === "standard" ? category : hub.playSegment;
  const pathRe = new RegExp(`/missions/${missionPath}(?:/\\d+)?/?`, "i");
  const navRe =
    category === "missions-stego"
      ? /href\s*=\s*["']\/missions\/(?:stego|playit\/stego)\//i
      : new RegExp(`href\\s*=\\s*["']/missions/${missionPath}/`, "i");
  const checks: { label: string; re: RegExp }[] = [
    {
      label: `${category} mission hub URL`,
      re: pathRe
    },
    {
      label: maintenance
        ? "HTS nightly maintenance window"
        : missionMissing
          ? "HTS mission instance not deployed (404)"
          : "Login required for mission access",
      re: maintenance
        ? HTS_MAINTENANCE_RE
        : missionMissing
          ? HTS_MISSION_NOT_FOUND_RE
          : HTS_AUTH_GATE_RE
    },
    {
      label: "HTS ethical hacking training ground",
      re: maintenance
        ? /HackThisSite\.org|hackthissite\.org/i
        : /HackThisSite\.org is a free, safe and legal training ground/i
    },
    {
      label: "Mission challenge nav category",
      re: navRe
    }
  ];
  for (const { label, re } of checks) {
    const m = corpus.match(re);
    if (m) hits.push({ label, sample: m[0].slice(0, 100) });
  }
  if (hits.length < 3) return NEGATIVE;
  const note = maintenance
    ? `HTS ${category} mission hub is offline for nightly maintenance — challenge content unreachable until backup window completes`
    : missionMissing
      ? `HTS ${category} mission instance URL is indexed but returns 404 — documents wargame challenge slot not yet deployed on this node`
      : (HTS_LOGIN_GATED_MISSION_NOTES[category] ?? `HTS ${category} mission hub is login-gated`);
  return {
    fired: true,
    confidence: hits.length >= 4 ? 0.9 : 0.87,
    evidence: {
      category,
      markers: hits.slice(0, 4),
      note
    }
  };
};

