// --- Credentials or secrets left in HTML comments (Mutillidae-style misconfig) -------
const htmlCommentCredentialDisclosure: Rule = async (ctx) => {
  const re =
    /<!--[\s\S]{0,1200}?(?:database\s+password|db\s+password|password\s+is\s+set\s+to|admin\s+password\s+is|SECRET:\s*\w*(?:password|passwd|credential|api[_-]?key))[\s\S]{0,800}?-->/i;
  const m = ctx.combined.match(re);
  if (m) {
    return {
      fired: true,
      confidence: 0.9,
      evidence: {
        sample: m[0].slice(0, 220).replace(/\s+/g, " ").trim(),
        note: "HTML comment discloses database or admin credentials viewable in page source"
      }
    };
  }
  const passwordFormSecret =
    /<form[\s\S]{0,900}?(?:name\s*=\s*["']password["']|type\s*=\s*["']password["'])[\s\S]{0,1400}?<!--\s*[a-z0-9]{6,}\s*-->/i;
  const bare = ctx.combined.match(passwordFormSecret);
  if (bare) {
    const secret = bare[0].match(/<!--\s*([a-z0-9]{6,})\s*-->/)?.[1];
    return {
      fired: true,
      confidence: 0.88,
      evidence: {
        sample: bare[0].slice(0, 220).replace(/\s+/g, " ").trim(),
        secretHint: secret?.slice(0, 24),
        note: "HTML comment beside password form discloses credential viewable in page source"
      }
    };
  }
  const base64FormSecret =
    /<form[\s\S]{0,900}?(?:name\s*=\s*["']password["']|type\s*=\s*["']password["'])[\s\S]{0,1400}?<!--\s*[A-Za-z0-9+/]{12,}={0,2}\s*-->/i;
  const b64 = ctx.combined.match(base64FormSecret);
  if (b64) {
    const secret = b64[0].match(/<!--\s*([A-Za-z0-9+/]{12,}={0,2})\s*-->/)?.[1];
    return {
      fired: true,
      confidence: 0.87,
      evidence: {
        sample: b64[0].slice(0, 220).replace(/\s+/g, " ").trim(),
        secretHint: secret?.slice(0, 24),
        note: "HTML comment beside password form discloses base64-encoded credential viewable in page source"
      }
    };
  }
  const syntheticPortal =
    /<!--[\s\S]{0,1600}?(?:apim-subscription-key\s*:\s*[a-z0-9]{16,}|dev_admin\s*:\s*[^\s<]+@[^\s<]+\s*\/\s*\S+|db_conn\s*:[\s\S]{0,200}?Password\s*=\s*[^;\s<]+)[\s\S]{0,800}?-->/i;
  const portal = ctx.combined.match(syntheticPortal);
  if (portal) {
    return {
      fired: true,
      confidence: 0.91,
      evidence: {
        sample: portal[0].slice(0, 220).replace(/\s+/g, " ").trim(),
        note: "HTML comment discloses API keys, admin credentials, or database connection strings in page source"
      }
    };
  }
  const ctfTokenComment =
    /<!--\s*[A-Za-z0-9+/]{12,}={0,2}\s*-->[\s\S]{0,600}?(?:hidden tokens|flagCES|token hunt|decode|cipher)/i;
  const ctfComment = ctx.combined.match(ctfTokenComment);
  if (ctfComment) {
    const secret = ctfComment[0].match(/<!--\s*([A-Za-z0-9+/]{12,}={0,2})\s*-->/)?.[1];
    return {
      fired: true,
      confidence: 0.86,
      evidence: {
        sample: ctfComment[0].slice(0, 220).replace(/\s+/g, " ").trim(),
        secretHint: secret?.slice(0, 24),
        note: "HTML comment contains base64-encoded CTF token visible in page source"
      }
    };
  }
  return NEGATIVE;
};

// --- VAmPI (OWASP vulnerable API) live oracles ---------------------------------
function isVampiHost(ctx: RuleContext): boolean {
  try {
    const host = new URL(ctx.origin).hostname.toLowerCase();
    if (host.includes("vampi")) return true;
  } catch {
    /* ignore */
  }
  return /VAmPI the Vulnerable API|VAmPI is a vulnerable on purpose API/i.test(ctx.combined);
}

async function tryVampiLabJwt(
  ctx: RuleContext
): Promise<{ token: string; username: string } | null> {
  const loginUrl = new URL("/users/v1/login", ctx.origin).toString();
  for (const creds of [
    { username: "name1", password: "pass1" },
    { username: "name2", password: "pass2" }
  ]) {
    const r = await ctx.probe.get(loginUrl, {
      method: "POST",
      body: JSON.stringify(creds),
      headers: { "Content-Type": "application/json" },
      maxBytes: 4096,
      timeoutMs: 15000
    });
    if (r.status < 200 || r.status >= 300) continue;
    try {
      const data = JSON.parse(r.body) as { auth_token?: string; status?: string };
      if (data.auth_token && data.status === "success") {
        return { token: data.auth_token, username: creds.username };
      }
    } catch {
      /* try next credential */
    }
  }
  return null;
}

const vampiUserBolaLiveOracle: Rule = async (ctx) => {
  if (!isVampiHost(ctx)) return NEGATIVE;
  const auth = await tryVampiLabJwt(ctx);
  if (!auth) return NEGATIVE;
  const victim = auth.username === "name1" ? "name2" : "name1";
  const profileUrl = new URL(`/users/v1/${victim}`, ctx.origin).toString();
  const doc = await ctx.probe.get(profileUrl, {
    maxBytes: 4096,
    timeoutMs: 15000,
    headers: { Authorization: `Bearer ${auth.token}` }
  });
  if (doc.status < 200 || doc.status >= 300) return NEGATIVE;
  try {
    const data = JSON.parse(doc.body) as { username?: string; email?: string };
    if (data.username !== victim || !data.email) return NEGATIVE;
    return {
      fired: true,
      confidence: 0.94,
      evidence: {
        profileUrl,
        caller: auth.username,
        victim,
        email: data.email,
        snippet: doc.body.slice(0, 200).trim(),
        note: `VAmPI GET /users/v1/${victim} returns another user's profile for authenticated ${auth.username} — BOLA oracle (API1)`
      }
    };
  } catch {
    return NEGATIVE;
  }
};

