const unauthenticatedApiRoutes: Rule = async (ctx) => {
  const juiceShopHit = await probeJuiceShopProductsSearchApi(ctx);
  if (juiceShopHit?.fired) return juiceShopHit;

  const openvaultHit = await probeOpenvaultBankRailwayApi(ctx);
  if (openvaultHit?.fired) return openvaultHit;

  const buggyBuyHit = await probeBuggyBuyExternalApi(ctx);
  if (buggyBuyHit?.fired) return buggyBuyHit;

  const paths = [
    ...new Set([
      ...extractApiPaths(ctx.combined, 10),
      ...(await fetchOpenApiGetPathsWithDetails(ctx, 10)),
      ...DEBUG_API_PATHS,
      ...(/openvaultbank\.com|OpenVault Bank/i.test(ctx.combined) ? OPENVAULT_API_FALLBACK_PATHS : [])
    ])
  ];
  if (paths.length === 0) return NEGATIVE;
  const externalBases = extractExternalApiBases(ctx.combined, ctx.origin, 4);
  const urls = buildApiProbeUrls(paths, ctx.origin, externalBases, 18);
  const docs = await ctx.probe.getMany(urls, { maxBytes: 8192 }, 4);
  const open: { path: string; status: number; sample: string; host?: string }[] = [];
  for (const [url, r] of docs) {
    if (r.status < 200 || r.status >= 300) continue;
    const ct = r.headers["content-type"] || "";
    if (!/json/i.test(ct) && !/^\s*[\[{]/.test(r.body.trim())) continue;
    if (/unauthorized|login required|sign in|authentication/i.test(r.body.slice(0, 500))) continue;
    const parsed = new URL(url);
    const path = parsed.pathname;
    const sensitive =
      /secret_key|admin_default_password|password|is_admin|plaintext/i.test(r.body) ||
      /\/api\/debug\//i.test(path);
    if (!sensitive && !/"(?:id|name|email|username|data)"\s*:/.test(r.body.slice(0, 400))) continue;
    open.push({
      path,
      status: r.status,
      sample: r.body.slice(0, 120).trim(),
      host: parsed.hostname
    });
  }
  if (open.length === 0) return NEGATIVE;
  return {
    fired: true,
    confidence: 0.85,
    evidence: {
      routes: open.slice(0, 6),
      note: "JSON API routes returned data without auth challenge"
    }
  };
};

const jwtAlgNoneProbe: Rule = async (ctx) => {
  const usesJwt =
    /Bearer\s+|Authorization.*(?:jwt|token)|jsonwebtoken|jose\.|jwt\.(?:sign|verify|decode)/i.test(
      ctx.combined
    );
  const paths = new Set(extractApiPaths(ctx.combined, 6));
  for (const p of ["/api/me", "/api/user", "/api/profile", "/api/auth/session", "/api/users"]) {
    paths.add(p);
  }
  if (JUICE_SHOP_HOST_RE.test(ctx.origin) || JUICE_SHOP_HOST_RE.test(ctx.combined)) {
    paths.add("/rest/user/authentication-details");
  }
  if (paths.size === 0 && !usesJwt) return NEGATIVE;

  const now = Math.floor(Date.now() / 1000);
  const algNoneToken = buildAlgNoneJwt({
    sub: "thugir-probe-user",
    role: "admin",
    iat: now,
    exp: now + 3600
  });
  const badToken = "thugir.invalid.probe.token";

  for (const path of [...paths].slice(0, 6)) {
    let url: string;
    try {
      url = new URL(path, ctx.origin).toString();
    } catch {
      continue;
    }
    const [noAuth, badAuth, noneAuth] = await Promise.all([
      ctx.probe.get(url, { maxBytes: 4096 }),
      ctx.probe.get(url, { maxBytes: 4096, headers: { Authorization: `Bearer ${badToken}` } }),
      ctx.probe.get(url, {
        maxBytes: 4096,
        headers: { Authorization: `Bearer ${algNoneToken}` }
      })
    ]);

    if (
      looksAuthChallenge(noAuth) &&
      looksAuthChallenge(badAuth) &&
      looksAuthGatedJson(noneAuth)
    ) {
      return {
        fired: true,
        confidence: 0.88,
        evidence: {
          path,
          note: "Endpoint rejected unauthenticated and malformed tokens but accepted a forged alg:none JWT",
          statusWithoutAuth: noAuth.status,
          statusWithMalformedToken: badAuth.status,
          statusWithAlgNone: noneAuth.status,
          responseSample: noneAuth.body.slice(0, 150).trim()
        }
      };
    }
  }
  return NEGATIVE;
};

