// --- Pwnshop route-specific oracles (PWN-040 SSTI, PWN-038 path traversal) ---------
const PWNSHOP_SSTI_MARKERS: { label: string; re: RegExp }[] = [
  { label: "PWN-040 SSTI registry ID", re: /PWN-040/i },
  { label: "Seller preview template endpoint", re: /\/seller\/preview\?template=/i },
  { label: "EJS render SSTI oracle", re: /ejs\.render\s*\(\s*\)|&lt;%= 7\*7 %&gt;[\s\S]{0,120}49/i },
  { label: "SSTI storefront preview title", re: /SSTI\s*(?:→|->)?\s*RCE[\s\S]{0,80}Seller Storefront Preview/i }
];

const PWNSHOP_PATH_TRAVERSAL_MARKERS: { label: string; re: RegExp }[] = [
  { label: "PWN-038 path traversal registry ID", re: /PWN-038/i },
  { label: "Invoice download file param endpoint", re: /GET \/download\?file=/i },
  { label: "path.join traversal payload docs", re: /path\.join\s*\(\s*\)|invoices\/\.\.\/\.\.\//i },
  { label: "Path Traversal Invoice Download title", re: /Path Traversal[\s\S]{0,80}Invoice Download/i }
];

function pwnshopRouteOracle(
  ctx: RuleContext,
  pathRe: RegExp,
  markers: { label: string; re: RegExp }[],
  note: string
): RuleResult {
  const pageUrl = ctx.home.finalUrl || ctx.scanUrl || ctx.origin;
  const urlCorpus = [pageUrl, ctx.scanUrl].filter(Boolean).join("\n");
  if (!/pwnshop|ctfsecurity\.com/i.test(ctx.combined + urlCorpus)) return NEGATIVE;
  const onRoute = pathRe.test(urlCorpus);
  const hits: { label: string; sample: string }[] = [];
  for (const m of markers) {
    const match = ctx.combined.match(m.re);
    if (match) hits.push({ label: m.label, sample: match[0].slice(0, 100) });
  }
  if (hits.length === 0) return NEGATIVE;
  if (!onRoute && hits.length < 2) return NEGATIVE;
  return {
    fired: true,
    confidence: onRoute && hits.length >= 2 ? 0.91 : hits.length >= 3 ? 0.9 : 0.87,
    evidence: { markers: hits.slice(0, 4), note }
  };
}

const clientSidePwnshopSstiOracle: Rule = async (ctx) =>
  pwnshopRouteOracle(
    ctx,
    /\/seller\/preview\b/i,
    PWNSHOP_SSTI_MARKERS,
    "Pwnshop /seller/preview?template= passes raw query input to ejs.render() — SSTI (PWN-040)"
  );

const clientSidePwnshopPathTraversalOracle: Rule = async (ctx) =>
  pwnshopRouteOracle(
    ctx,
    /\/download\b/i,
    PWNSHOP_PATH_TRAVERSAL_MARKERS,
    "Pwnshop GET /download?file= joins user input via path.join() without resolved-path validation (PWN-038)"
  );

function isPwnshopHost(ctx: RuleContext): boolean {
  return /pwnshop|ctfsecurity\.com/i.test(ctx.origin);
}

const pwnshopDebugInfoLiveOracle: Rule = async (ctx) => {
  if (!isPwnshopHost(ctx)) return NEGATIVE;
  const url = new URL("/debug/info", ctx.origin).toString();
  const doc = await ctx.probe.get(url, { maxBytes: 4096 });
  if (doc.status < 200 || doc.status >= 300) return NEGATIVE;
  const ct = doc.headers["content-type"] || "";
  if (!/json/i.test(ct) && !/^\s*\{/.test(doc.body.trim())) return NEGATIVE;
  const markers: { label: string; sample: string }[] = [];
  for (const { label, re } of [
    { label: "sessionSecret in debug JSON", re: /"sessionSecret"\s*:\s*"[^"]{6,}"/i },
    { label: "CHAT_OVERRIDE_TOKEN in debug JSON", re: /"CHAT_OVERRIDE_TOKEN"\s*:\s*"[^"]{6,}"/i },
    { label: "dbConfig credentials in debug JSON", re: /"dbConfig"\s*:\s*\{[^}]*"user"\s*:/i }
  ]) {
    const m = doc.body.match(re);
    if (m) markers.push({ label, sample: m[0].slice(0, 80) });
  }
  if (markers.length === 0) return NEGATIVE;
  return {
    fired: true,
    confidence: markers.length >= 2 ? 0.93 : 0.91,
    evidence: {
      url,
      markers: markers.slice(0, 3),
      snippet: doc.body.slice(0, 200).trim(),
      note: "Pwnshop GET /debug/info returns session secrets and override tokens without authentication (PWN-018)"
    }
  };
};

const pwnshopEventsAuditLiveOracle: Rule = async (ctx) => {
  if (!isPwnshopHost(ctx)) return NEGATIVE;
  const url = new URL("/api/v1/events", ctx.origin).toString();
  const doc = await ctx.probe.get(url, { maxBytes: 8192 });
  if (doc.status < 200 || doc.status >= 300) return NEGATIVE;
  const ct = doc.headers["content-type"] || "";
  if (!/json/i.test(ct) && !/^\s*\{/.test(doc.body.trim())) return NEGATIVE;
  if (!/"logs"\s*:\s*\[/.test(doc.body) || !/"action"\s*:/.test(doc.body)) return NEGATIVE;
  if (!/"count"\s*:\s*\d+/.test(doc.body)) return NEGATIVE;
  return {
    fired: true,
    confidence: /"detail"\s*:/.test(doc.body) ? 0.92 : 0.9,
    evidence: {
      url,
      snippet: doc.body.slice(0, 240).trim(),
      note: "Pwnshop GET /api/v1/events returns unauthenticated audit log entries with action/detail fields (PWN-005)"
    }
  };
};

const pwnshopChatInitEmailEnumerationLiveOracle: Rule = async (ctx) => {
  if (!isPwnshopHost(ctx)) return NEGATIVE;
  const url = new URL("/chat/init", ctx.origin).toString();
  const missingEmail = `thugir-notfound-${Date.now()}@example.com`;
  const missingDoc = await ctx.probe.get(url, {
    method: "POST",
    body: JSON.stringify({ email: missingEmail }),
    headers: { "Content-Type": "application/json" },
    maxBytes: 2048
  });
  if (missingDoc.status < 200 || missingDoc.status >= 300) return NEGATIVE;
  if (!/"found"\s*:\s*false/i.test(missingDoc.body)) return NEGATIVE;
  const knownDoc = await ctx.probe.get(url, {
    method: "POST",
    body: JSON.stringify({ email: "admin@pwnshop.com" }),
    headers: { "Content-Type": "application/json" },
    maxBytes: 2048
  });
  if (knownDoc.status < 200 || knownDoc.status >= 300) return NEGATIVE;
  if (!/"found"\s*:\s*true/i.test(knownDoc.body)) return NEGATIVE;
  if (!/"user"\s*:\s*\{/.test(knownDoc.body) || !/"email"\s*:/.test(knownDoc.body)) return NEGATIVE;
  return {
    fired: true,
    confidence: 0.93,
    evidence: {
      url,
      missingEmail,
      missingSnippet: missingDoc.body.slice(0, 120).trim(),
      knownSnippet: knownDoc.body.slice(0, 200).trim(),
      note: "Pwnshop POST /chat/init returns found:true with user profile for registered emails and found:false for unknown addresses — username enumeration (PWN-037)"
    }
  };
};

const pwnshopForgotPasswordEmailEnumerationLiveOracle: Rule = async (ctx) => {
  if (!isPwnshopHost(ctx)) return NEGATIVE;
  const url = new URL("/forgot-password", ctx.origin).toString();
  const missingEmail = `thugir-notfound-${Date.now()}@example.com`;
  const missingDoc = await ctx.probe.get(url, {
    method: "POST",
    body: `email=${encodeURIComponent(missingEmail)}`,
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    maxBytes: 8192
  });
  if (missingDoc.status < 200 || missingDoc.status >= 400) return NEGATIVE;
  if (!/no account found/i.test(missingDoc.body)) return NEGATIVE;
  const knownDoc = await ctx.probe.get(url, {
    method: "POST",
    body: "email=admin%40pwnshop.com",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    maxBytes: 8192
  });
  if (knownDoc.status < 200 || knownDoc.status >= 400) return NEGATIVE;
  if (!/password reset link has been sent/i.test(knownDoc.body)) return NEGATIVE;
  if (!/admin@pwnshop\.com/i.test(knownDoc.body)) return NEGATIVE;
  return {
    fired: true,
    confidence: 0.93,
    evidence: {
      url,
      missingEmail,
      missingSnippet: missingDoc.body.match(/alert-err[^<]*<\/i>\s*([^<]+)/i)?.[1]?.trim() ?? "",
      knownSnippet: knownDoc.body.match(/alert-ok[^<]*<\/i>\s*([^<]+)/i)?.[1]?.trim() ?? "",
      note: "Pwnshop POST /forgot-password returns distinct success vs no-account messages for registered vs unknown emails — password-reset enumeration oracle"
    }
  };
};

