  const urlCorpus = [pageUrl, ctx.scanUrl].filter(Boolean).join("\n");
  const corpus = `${ctx.combined}\n${pageUrl}${ctx.scanUrl && ctx.scanUrl !== pageUrl ? `\n${ctx.scanUrl}` : ""}`;
